INSERT INTO compact_digest_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_digest_existing p LEFT JOIN scheduled_plan t ON BINARY p.row_key=BINARY CAST(t.id AS CHAR) WHERE p.table_name='scheduled_plan' AND (t.id IS NULL OR BINARY p.row_sha<>BINARY SHA2(CAST(JSON_ARRAY(t.`id`,t.`plan_id`,t.`kind`,t.`owner_user_id`,t.`owner_name`,t.`name`,t.`cron_expression`,t.`time_zone`,t.`enabled`,t.`revision`,t.`next_fire_at`,t.`payload_version`,t.`payload_json`,t.`created_at`,t.`updated_at`) AS CHAR CHARACTER SET utf8mb4),256));
INSERT INTO compact_digest_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_digest_existing p LEFT JOIN audit_event t ON BINARY p.row_key=BINARY CAST(t.id AS CHAR) WHERE p.table_name='audit_event' AND (t.id IS NULL OR BINARY p.row_sha<>BINARY SHA2(CAST(JSON_ARRAY(t.`legacy_clock_json`,t.`id`,t.`event_id`,t.`kind`,t.`owner_user_id`,t.`actor_user_id`,t.`resource_type`,t.`resource_id`,t.`detection_model_id`,t.`session_id`,t.`message_id`,t.`run_id`,t.`journal_run_id`,t.`sequence_no`,t.`request_id`,t.`action`,t.`revision`,t.`content_sha256`,t.`previous_sha256`,t.`event_sha256`,t.`quantity`,t.`unit`,t.`request_scope`,t.`policy_version`,t.`outcome`,t.`observed_at`,t.`occurred_at`,t.`payload_version`,t.`payload_json`,t.`legacy_source`,t.`legacy_key`,t.`call_id`,t.`digest_legacy_detail_json`) AS CHAR CHARACTER SET utf8mb4),256));
INSERT INTO compact_digest_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_digest_existing p LEFT JOIN runtime_state t ON BINARY p.row_key=BINARY CAST(JSON_ARRAY(t.namespace,t.owner_id,t.scope_key) AS CHAR CHARACTER SET utf8mb4) WHERE p.table_name='runtime_state' AND (t.namespace IS NULL OR BINARY p.row_sha<>BINARY SHA2(CAST(JSON_ARRAY(t.`legacy_clock_json`,t.`namespace`,t.`owner_id`,t.`scope_key`,t.`session_id`,t.`state_key`,t.`revision`,t.`state_code`,t.`current_ref`,t.`counter_value`,t.`provider`,t.`credential_sha256`,t.`actor_user_id`,t.`request_id`,t.`window_started_at`,t.`window_ends_at`,t.`payload_version`,t.`payload_json`,t.`created_at`,t.`updated_at`) AS CHAR CHARACTER SET utf8mb4),256));
