-- Actual V65 five-table/39-column copy. ECS execution and frozen source only.
-- No source writes, active writers, clock inference, source hash replacement, or FK disabling.
-- BEGIN/COMMIT are this segment only; the outer migration owns source freeze and quarantine.
SET NAMES utf8mb4;
SET @compact_digest_old_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=3200000;
CREATE TEMPORARY TABLE compact_digest_guard(ok TINYINT NOT NULL CHECK(ok=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_digest_source_rows(table_name VARCHAR(64) COLLATE utf8mb4_bin NOT NULL,row_key VARCHAR(512) COLLATE utf8mb4_bin NOT NULL,row_sha CHAR(64) NOT NULL,PRIMARY KEY(table_name,row_key)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_digest_sequences(table_name VARCHAR(64) COLLATE utf8mb4_bin NOT NULL PRIMARY KEY,next_id BIGINT UNSIGNED NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_digest_existing(table_name VARCHAR(64) NOT NULL,row_key VARCHAR(512) COLLATE utf8mb4_bin NOT NULL,row_sha CHAR(64) NOT NULL,PRIMARY KEY(table_name,row_key)) ENGINE=InnoDB;
SET @compact_digest_shared_next=(SELECT GREATEST(COALESCE((SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='workflow_instance'),1),COALESCE((SELECT next_id FROM compact_digest_sequences WHERE table_name='quality_digest_run'),1)));
SET @compact_digest_ddl=CONCAT('ALTER TABLE workflow_instance AUTO_INCREMENT=',CAST(@compact_digest_shared_next AS CHAR));
PREPARE compact_digest_statement FROM @compact_digest_ddl; EXECUTE compact_digest_statement; DEALLOCATE PREPARE compact_digest_statement;
SET @compact_digest_shared_next=(SELECT GREATEST(COALESCE((SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='audit_event'),1),COALESCE((SELECT next_id FROM compact_digest_sequences WHERE table_name='quality_digest_audit'),1)));
SET @compact_digest_ddl=CONCAT('ALTER TABLE audit_event AUTO_INCREMENT=',CAST(@compact_digest_shared_next AS CHAR));
PREPARE compact_digest_statement FROM @compact_digest_ddl; EXECUTE compact_digest_statement; DEALLOCATE PREPARE compact_digest_statement;
SET @compact_digest_clock_begin=UTC_TIMESTAMP(6);
START TRANSACTION;
COMMIT;
SET SESSION group_concat_max_len=@compact_digest_old_concat;
-- Explicit schedule AUTO_INCREMENT preserves deleted historical high-water marks, not merely MAX(id)+1.
SET @compact_digest_next=(SELECT next_id FROM compact_digest_sequences WHERE table_name='quality_digest_schedule');
SET @compact_digest_ddl=CONCAT('ALTER TABLE scheduled_plan AUTO_INCREMENT=',CAST(@compact_digest_next AS CHAR));
PREPARE compact_digest_statement FROM @compact_digest_ddl; EXECUTE compact_digest_statement; DEALLOCATE PREPARE compact_digest_statement;
